-- Read tools: actual tenant/private RLS, composite scopes, UUID pages and identity.
-- This script is only run against a disposable local database; fixtures roll back.
begin;
do $$
declare u uuid:=gen_random_uuid();v uuid:=gen_random_uuid();b uuid:=gen_random_uuid();reader uuid:=gen_random_uuid();w uuid;other uuid;obj uuid;other_obj uuid;
 rec uuid;related uuid;foreign_rec uuid;private_list uuid;visible_list uuid;foreign_list uuid;i uuid;other_i uuid;mail uuid;foreign_mail uuid;
 client_id uuid;cid uuid;access_hash text:=repeat('a',64);reader_cid uuid;reader_hash text:=repeat('b',64);resource text:='https://zyliad.example.test/api/mcp';r jsonb;first_page jsonb;
begin
 insert into auth.users(id,email) values(u,'context-owner@example.test'),(v,'context-member@example.test'),(b,'context-other@example.test'),(reader,'context-reader@example.test');
 perform set_config('request.jwt.claim.sub',u::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated')::text,true);
 w:=public.create_workspace('Context A');
 update public.memberships set display_name='Context owner' where workspace_id=w and user_id=u;
 insert into public.memberships(workspace_id,user_id,role,display_name) values(w,v,'member','Visible member'),(w,reader,'viewer','Limited reader');
 select id into obj from public.objects where workspace_id=w and slug='people';
 insert into public.attributes(workspace_id,object_id,key,name,type) values(w,obj,'job_title','Fonction','text');
 insert into public.records(workspace_id,object_id,display_name,attributes) values(w,obj,'Visible A','{"job_title":"Directrice"}') returning id into rec;
 insert into public.records(workspace_id,object_id,display_name) values(w,obj,'Related A') returning id into related;
 insert into public.record_relations(workspace_id,source_id,target_id,label) values(w,rec,related,'Collègue');
 insert into public.notes(workspace_id,record_id,title,content,private,author_id) values(w,rec,'Visible note','Authorized context',true,u),(w,rec,'Private member note','SECRET PRIVATE NOTE',true,v);
 insert into public.tasks(workspace_id,record_id,title) values(w,rec,'First task'),(w,rec,'Second task'),(w,rec,'Third task');
 insert into public.lists(workspace_id,object_id,name,visibility,creator_id) values(w,obj,'Visible list','workspace',u) returning id into visible_list;
 insert into public.list_entries(workspace_id,list_id,record_id) values(w,visible_list,rec),(w,visible_list,related);
 insert into public.lists(workspace_id,object_id,name,visibility,creator_id) values(w,obj,'SECRET PRIVATE LIST','private',v) returning id into private_list;
 insert into public.list_entries(workspace_id,list_id,record_id) values(w,private_list,rec);
 insert into public.integrations(workspace_id,user_id,provider,email,status) values(w,u,'gmail','context-owner@example.test','connected') returning id into i;
 insert into public.integrations(workspace_id,user_id,provider,email,status) values(w,v,'gmail','context-member@example.test','connected') returning id into other_i;
 insert into public.communications(workspace_id,user_id,integration_id,provider_id,kind,thread_id,subject,body,record_id,received_at,content_complete)
 values(w,u,i,'first','email','same-external-thread','Visible first','First authorized reply',rec,now(),true) returning id into mail;
 insert into public.communications(workspace_id,user_id,integration_id,provider_id,kind,thread_id,subject,body,record_id,received_at,content_complete)
 values(w,u,i,'second','email','same-external-thread','Visible second','Second authorized reply',rec,now(),true),
       (w,v,other_i,'third','email','same-external-thread','SECRET PRIVATE EMAIL','Hidden other-user body',rec,now(),true);
 insert into relay_private.reader_record_access(workspace_id,user_id,record_id) values(w,reader,rec);
 perform set_config('request.jwt.claim.sub',b::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',b,'role','authenticated')::text,true);
 other:=public.create_workspace('Context B');
 select id into other_obj from public.objects where workspace_id=other and slug='people';
 insert into public.records(workspace_id,object_id,display_name) values(other,other_obj,'SECRET TENANT B') returning id into foreign_rec;
 insert into public.lists(workspace_id,object_id,name) values(other,other_obj,'SECRET TENANT LIST') returning id into foreign_list;
 insert into public.list_entries(workspace_id,list_id,record_id) values(other,foreign_list,foreign_rec);
 insert into relay_private.mcp_clients(name,redirect_uris) values('Context fixture',array['http://127.0.0.1:45678/callback']) returning id into client_id;
 insert into relay_private.mcp_connections(client_id,workspace_id,user_id,scopes,resource) values(client_id,w,u,array['records:read','tasks:read','notes:read','communications:read','configuration:read'],resource) returning id into cid;
 insert into relay_private.mcp_tokens(token_hash,connection_id,kind,expires_at) values(access_hash,cid,'access',now()+interval '1 hour');
 insert into relay_private.mcp_connections(client_id,workspace_id,user_id,scopes,resource) values(client_id,w,reader,array['records:read','tasks:read','notes:read','configuration:read'],resource) returning id into reader_cid;
 insert into relay_private.mcp_tokens(token_hash,connection_id,kind,expires_at) values(reader_hash,reader_cid,'access',now()+interval '1 hour');
 execute 'set local role service_role';
 r:=public.mcp_request(access_hash,'connection',jsonb_build_object('resource',resource));
 if r->'user'->>'id'<>u::text or r->'user'->>'role'<>'owner' or r->'workspace'->>'id'<>w::text or r->'workspace'->>'timezone'<>'Europe/Paris' or r::text like '%context-owner@example.test%' then raise exception 'Identity/metadata not minimized: %',r;end if;
 r:=public.mcp_request(access_hash,'record',jsonb_build_object('resource',resource,'record_id',rec));
 if r->'record'->>'id'<>rec::text or r->'record'->'attributes'<>'{}'::jsonb or not (r->'record') ? 'version' or not (r->'record'->>'attributes_partial')::boolean then raise exception 'Record/attribute selection failed: %',r;end if;
 r:=public.mcp_request(access_hash,'record',jsonb_build_object('resource',resource,'record_id',rec,'attribute_keys','["job_title"]'::jsonb));
 if r->'record'->'attributes'->>'job_title'<>'Directrice' or (r->'record'->>'attributes_partial')::boolean then raise exception 'Selected custom field missing: %',r;end if;
 r:=public.mcp_request(access_hash,'record',jsonb_build_object('resource',resource,'record_id',foreign_rec));
 if r->>'error'<>'not_found' then raise exception 'Foreign record accessible';end if;
 r:=public.mcp_request(access_hash,'records',jsonb_build_object('resource',resource,'record_ids',jsonb_build_array(rec,foreign_rec,gen_random_uuid())));
 if jsonb_array_length(r->'records')<>1 or jsonb_array_length(r->'unavailable_ids')<>2 or r::text like '%SECRET TENANT%' then raise exception 'Batch tenant isolation failed: %',r;end if;
 r:=public.mcp_request(access_hash,'record_context',jsonb_build_object('resource',resource,'record_id',rec,'sections','["task","note","email"]'::jsonb,'limit',1));
 if r ? 'error' or r::text like '%SECRET%' or jsonb_array_length(r->'sections'->'note'->'data')<>1 or jsonb_array_length(r->'sections'->'task'->'data')<>1 or not (r->>'partial')::boolean then raise exception 'Context scope/RLS/page failed: %',r;end if;
 r:=public.mcp_request(access_hash,'record_context',jsonb_build_object('resource',resource,'record_id',rec,'sections','["document"]'::jsonb,'limit',1));
 if r->>'error'<>'forbidden' then raise exception 'Section scope escalated';end if;
 r:=public.mcp_request(access_hash,'record_context',jsonb_build_object('resource',resource,'record_id',foreign_rec,'sections','["task"]'::jsonb,'limit',1));
 if r->>'error'<>'not_found' then raise exception 'Foreign context accessible';end if;
 r:=public.mcp_request(access_hash,'record_context',jsonb_build_object('resource',resource,'record_id',rec,'sections','["task"]'::jsonb,'limit',1,'since',now()+interval '1 day','until',now()));
 if r->>'error'<>'validation_error' then raise exception 'Reversed period accepted';end if;
 r:=public.mcp_request(access_hash,'members',jsonb_build_object('resource',resource,'query','Visible')); 
 if jsonb_array_length(r->'data')<>1 or r->'data'->0->>'id'<>v::text or r::text like '%context-member@example.test%' then raise exception 'Member selection/PII failed: %',r;end if;
 first_page:=public.mcp_request(access_hash,'list_records',jsonb_build_object('resource',resource,'list_id',visible_list,'limit',1));
 if jsonb_array_length(first_page->'data')<>1 or not (first_page->>'has_more')::boolean then raise exception 'List first page invalid: %',first_page;end if;
 r:=public.mcp_request(access_hash,'list_records',jsonb_build_object('resource',resource,'list_id',visible_list,'limit',1,'cursor',first_page->>'next_cursor'));
 if jsonb_array_length(r->'data')<>1 or (r->>'has_more')::boolean or r->'data'->0->>'id'=first_page->'data'->0->>'id' then raise exception 'List pagination duplicate or wrong: %',r;end if;
 r:=public.mcp_request(access_hash,'list_records',jsonb_build_object('resource',resource,'list_id',private_list));
 if r->>'error'<>'not_found' then raise exception 'Private list exposed';end if;
 r:=public.mcp_request(access_hash,'list_records',jsonb_build_object('resource',resource,'list_id',foreign_list));
 if r->>'error'<>'not_found' then raise exception 'Foreign list exposed';end if;
 r:=public.mcp_request(access_hash,'thread',jsonb_build_object('resource',resource,'id',mail));
 if jsonb_array_length(r->'data')<>2 or r::text like '%SECRET PRIVATE EMAIL%' then raise exception 'Thread crossed account permissions: %',r;end if;
 r:=public.mcp_request(access_hash,'relations',jsonb_build_object('resource',resource,'record_id',rec));
 if jsonb_array_length(r->'data')<>1 or r->'data'->0->'record'->>'id'<>related::text then raise exception 'Relation not found: %',r;end if;
 r:=public.mcp_request(reader_hash,'relations',jsonb_build_object('resource',resource,'record_id',rec));
 if jsonb_array_length(r->'data')<>0 then raise exception 'Limited reader saw hidden relation';end if;
 r:=public.mcp_request(reader_hash,'list_records',jsonb_build_object('resource',resource,'list_id',visible_list));
 if jsonb_array_length(r->'data')<>1 or r::text like '%Related A%' then raise exception 'Limited reader saw hidden list record';end if;
 r:=public.mcp_request(reader_hash,'record',jsonb_build_object('resource',resource,'record_id',related));
 if r->>'error'<>'not_found' then raise exception 'Limited reader bypassed record RLS';end if;
 execute 'reset role';
 update relay_private.mcp_connections set scopes=array['records:read'] where id=cid;
 execute 'set local role service_role';
 r:=public.mcp_request(access_hash,'list_records',jsonb_build_object('resource',resource,'list_id',visible_list));
 if r->>'error'<>'forbidden' then raise exception 'Composite list permission ignored';end if;
 r:=public.mcp_request(access_hash,'record_context',jsonb_build_object('resource',resource,'record_id',rec,'sections','[]'::jsonb,'limit',1));
 if r ? 'error' or r->'sections'<>'{}'::jsonb then raise exception 'Record-only context failed: %',r;end if;
 execute 'reset role';
 update relay_private.mcp_connections set revoked_at=now() where id=cid;
 execute 'set local role service_role';
 r:=public.mcp_request(access_hash,'connection',jsonb_build_object('resource',resource));
 if r->>'error'<>'unauthorized' then raise exception 'Revoked connection could still read';end if;
 execute 'reset role';
 if has_function_privilege('authenticated','relay_private.mcp_read(uuid,text,jsonb)','execute') or has_function_privilege('anon','public.mcp_request(text,text,jsonb)','execute') then raise exception 'Backend helper exposed to browser';end if;
 if not exists(select 1 from relay_private.mcp_audit where connection_id=cid and action='record_context' and result='forbidden') then raise exception 'Denied context not audited';end if;
 raise notice 'MCP context/identity/members/relations/lists/threads: scopes, private data, tenant/reader isolation, pagination, field selection, revocation and audit passed.';
end $$;
rollback;
